import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"復","description":"周易集解 - 復","frontmatter":{"title":"復","description":"周易集解 - 復"},"headers":[],"relativePath":"classics/jijie/024.md","filePath":"classics/jijie/024.md"}'),l={name:"classics/jijie/024.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="復" tabindex="-1">復 <a class="header-anchor" href="#復" aria-label="Permalink to “復”">​</a></h1><h2 id="復-1" tabindex="-1">復 <a class="header-anchor" href="#復-1" aria-label="Permalink to “復”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>復，亨。出入無疾，朋來無咎。反覆其道，七日來複。利有攸往。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：物不可以終盡，剝窮上反下，故受之以復也。</p><p>崔憬曰：夫易窮則有變，物極則反於初。故剝之為道，不可終盡，而受之於復也。</p><p>何妥曰：復者，歸本之名。群陰剝陽，至於幾盡，一陽來下，故稱反覆。陽氣復反，而得交通，故雲復亨也。</p><p>虞翻曰：謂出震成乾，入巽成坤。坎為疾，十二消息，不見坎象，故出入無疾。兌為朋，在內稱來；五陰從初，初陽正息而成兌，故朋來無咎矣。</p><p>案：易軌：一歲十二月，三百六十五日四分日之一。以坎、震、離、兌四方正卦，卦別六爻，爻生一氣。其餘六十卦，三百六十爻，爻主一日，當周天之數，餘五日四分日之一，以通閏餘者也。剝卦陽氣盡於九月之終，至十月末，純坤用事。坤卦將盡，則復陽來。隔坤之一卦六爻。為六日。復來成震，一陽爻生，為七日。故言｢反覆其道，七日來複｣。是其義也。天道玄邈，理絕希慕，先儒已論，雖各指於日月，後學尋討，猶未測其端倪。今舉約文，略陳梗概，以候來哲，如積薪者也。</p><p>虞翻曰：陽息臨成乾，小人道消，君子道長，故利有攸往矣。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：復亨，剛反動，而以順行，是以出入無疾，朋來無咎。反覆其道，七日來複，天行也。利有攸往，剛長也。復，其見天地之心乎。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>虞翻曰：陽息坤，與姤旁通。剛反交初，故亨。</p><p>虞翻曰：剛從艮入坤，從反震，故曰反動。坤順震行，故｢而以順行｣。陽不從上來反初，故不言剛自外來。是以明不遠之復，入坤出震義也。</p><p>侯果曰：陽上出，君子道長也。陰下入，小人道消也。動而以行，故｢出入無疾，朋來無咎｣矣。</p><p>虞翻曰：謂乾成坤，反出於震而來複，陽為道，故復其道。剛為晝日。消乾六爻。為六日。剛來反初，故｢七日來複，天行也｣。</p><p>侯果曰：五月天行至午，陽復而陰升也；十一月天行至子，陰復而陽升也。天地運往，陰陽升復，凡歷七月，故曰｢七日來複｣。此天之運行也。豳詩曰：一之日觱發，二之日慄烈。一之日，周之正月也；二之日，周之二月也。則古人呼月為日明矣。</p><p>荀爽曰：利往居五，剛道浸長也。</p><p>虞翻曰：坤為復。謂三複位時，離為見，坎為心。陽息臨成泰，乾天坤地。故｢見天地之心｣也。</p><p>荀爽曰：復者，冬至之卦。陽起初九，為天地心。萬物所始，吉凶之先，故曰｢見天地之心｣矣。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：雷在地中，復。先王以至日閉關，商旅不行，後不省方。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：先王謂乾初。至日冬至之日。坤闔為閉關。巽為商旅，為近利市三倍，姤巽伏初，故商旅不行。姤象曰：後以施命誥四方。今隱復下，故後不省方，復為陽始，姤則陰始。天地之始，陰陽之首。已言先王，又更言後，後，君也。六十四卦，唯此重耳。</p><p>宋衷曰：商旅不行，自天子至公侯，不省四方之事，將以輔遂陽體，成致君道也。制之者，王者之事。奉之者，為君之業也。故上言先王而下言後也。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，不遠復，無祗悔，元吉。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>崔憬曰：從坤反震，而變此爻，不遠復也。復而有應故獲元吉也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：不遠之復，以修身也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>侯果曰：祗，大也。往被陰剝，所以有悔。覺非遠復，故無大咎。以此修身，顔子之分矣。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，休復，吉。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：休復之吉，以下仁也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>王弼曰：得位居中。比初之上，而附順之下，仁之謂也。既處中位，親仁善鄰，復之休也。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，頻復，厲，無咎。</p><h2 id="六三注" tabindex="-1">六三注 <a class="header-anchor" href="#六三注" aria-label="Permalink to “六三注”">​</a></h2><p>虞翻曰：頻蹙也。三失位，故｢頻復，厲｣。動而之正，故無咎也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：頻復之厲，義無咎也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>侯果曰：處震之極，以陰居陽，懼其將危，頻蹙而復，履危反道，義亦無咎也。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，中行獨復。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：中行獨復，以從道也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：中謂初。震為行。初一陽爻，故稱獨。四得正應初，故曰｢中行獨復，以從道也｣。俗說以四位在五陰之中，而獨應復，非也。四在外體，又非內象，不在二五，何得稱｢中行｣耳？</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，敦復，無悔。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：敦復無悔，中以自考也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>侯果曰：坤為厚載，故曰敦復。體柔居剛，無應失位，所以有悔。能自考省，動不失中，故曰無悔矣。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，迷復，兇、有災眚。用行師，終有大敗，以其國君兇，至於十年不克徵。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>虞翻曰：坤冥為迷，高而無應，故兇。五變正時，坎為災眚，故有災眚也。</p><p>虞翻曰：三重位時，而體師象，故用行師。陰逆不順，坤為死喪，坎流血，故終有大敗。姤乾為君滅藏於坤，坤為異邦，故國君兇矣。</p><p>荀爽曰：坤為眾，故曰行師也。謂上行師，而距於初。陽息上升，必消群陰，故終有大敗。國君，謂初也。受命復道，當從下升。今上六行師，王誅必加。故以其國君兇也。</p><p>虞翻曰：坤為至，為十年。陰逆坎臨，故不克徵。謂五變設險，故帥師敗喪，君而無徵也。</p><p>何妥曰：理國之道，須進善納諫。迷而不復，安可牧民？以此行師，必敗績矣。敗乃思復，失道已遠。雖復十年乃徵，無所克矣。</p><p>案：坤為先迷，故曰迷復。坤又為師象，故曰行師。坤數十，十年之象也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：迷復之兇，反君道也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：姤乾為君，坤陰滅之，以國君兇，故曰反君道也。</p>',76)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
